for(const [code,cityAr,cityEn,nameAr,nameEn,lat,lon,wiki,factAr,factEn] of phase1Batch4){
 const country=countries.find(row=>row[0]===code);
 if(!country||originals.some(row=>row.code===code&&row.nameEn.toLocaleLowerCase()===nameEn.toLocaleLowerCase()))continue;
 const index=geo.tourism.length;
 const item={index,code,countryAr:country[1],countryEn:country[2],cityAr,cityEn,nameAr,nameEn,factAr,factEn,wiki,
  pointsAr:[factAr,'يقدم الموقع جانبًا مميزًا من تراث '+country[1]+' الجغرافي أو الثقافي.'],
  pointsEn:[factEn,'The location highlights a distinctive aspect of '+country[2]+'s geographical or cultural heritage.']};
 geo.tourism.push([nameAr,nameEn,factAr+' · '+cityAr+'، '+country[1]+'.',factEn+' · '+cityEn+', '+country[2]+'.',lat,lon]);
 originals.push(item);
 const group=byCode.get(code)||[];group.push(item);byCode.set(code,group);
}
